<script setup lang="ts">
import {readImageAsset} from '../../core/imageAsset'
import {computed,ref,watch} from 'vue'
import {Box,Button,Disclosure,DisclosureTrigger,Field,Footer,Header,Heading,Image,Modal,ModalBody,Select,Text,TextArea,TextField} from '../ui'
import {useEditor} from '../../composables/useEditor'
import {useImageDrafts} from '../../composables/useImageDrafts'
import {captureStyleAsset} from '../../core/styleAsset'
import {draftStyleSchema,imageDraftBundleSchema,type ImageDraftInput,type ImageDraftRun} from '../../core/imageDraftContract'
import {downloadFile} from '../../core/export'
import {readGeneratedReference,wholeImage} from '../../core/references'
import {referencePurposeLabels,type ReferencePurpose} from '../../core/referenceInputs'
import {imageDraftPlanStyle,imageDraftPlanReferences} from '../../core/imageDraftDesign'
import CompositionPlanView from '../harness/CompositionPlanView.vue'
import ImageDraftOriginView from './ImageDraftOriginView.vue'
const editor=useEditor(),drafts=useImageDrafts(),title=ref('论文插图视觉草稿'),content=ref(''),visual=ref(''),model=ref(''),aspect=ref<ImageDraftInput['aspect']>('landscape'),timeout=ref('360'),styleId=ref('current'),selected=ref<Record<string,ReferencePurpose>>({}),importing=ref(''),error=ref('')
try{const saved=JSON.parse(localStorage.getItem('fastfigure.image-drafts.v1')??'null') as {title?:string;content?:string;visual?:string;model?:string;aspect?:ImageDraftInput['aspect'];timeout?:string}|null;if(saved){title.value=saved.title??title.value;content.value=saved.content??'';visual.value=saved.visual??'';model.value=saved.model??'';aspect.value=['landscape','square','portrait'].includes(saved.aspect??'')?saved.aspect!:'landscape';timeout.value=['60','180','360','600'].includes(saved.timeout??'')?saved.timeout!:'360'}}catch{/* Optional local draft preferences. */}
watch(editor.imageDraftPlan,plan=>{if(plan){title.value=plan.plan.title;content.value=plan.plan.goal;visual.value='';error.value=''}},{immediate:true})
watch([title,content,visual,model,aspect,timeout],()=>{if(editor.imageDraftPlan.value)return;try{localStorage.setItem('fastfigure.image-drafts.v1',JSON.stringify({title:title.value,content:content.value,visual:visual.value,model:model.value,aspect:aspect.value,timeout:timeout.value}))}catch{/* Form remains usable without local storage. */}})
const running=computed(()=>drafts.runs.value.some(r=>r.status==='running')),styleOptions=computed(()=>[{value:'current',label:'当前容器风格'},...editor.styleLibrary.assets.value.map(s=>({value:s.id,label:s.name}))])
const outputKind=ref<'figure'|'illustration'>('figure')
const previewId=ref(''),previewRun=computed(()=>drafts.runs.value.find(r=>r.id===previewId.value))
const purposeOptions=Object.entries(referencePurposeLabels).map(([value,label])=>({value,label}))
function select(id:string,event:Event){if((event.target as HTMLInputElement).checked)selected.value={...selected.value,[id]:'style'};else{const next={...selected.value};delete next[id];selected.value=next}}
async function generate(){error.value='';try{if(drafts.pending.value){await drafts.start(drafts.pending.value);return}const composition=editor.imageDraftPlan.value,style=composition?imageDraftPlanStyle(composition):styleId.value==='current'?captureStyleAsset(editor.figure.value,editor.currentContainer.value.id):editor.styleLibrary.assets.value.find(s=>s.id===styleId.value);if(!style)throw new Error('所选风格已移除，请重新选择');const{id,name,updatedAt,designSystem,paperTheme,fontRoles,preset,paletteId,fontFamily,surface,colorIndex,colorMap,sketchStyle,roughness,lineStyle,guide}=style
  const references=composition?imageDraftPlanReferences(composition,editor.figure.value):Object.entries(selected.value).map(([id,purpose])=>{const ref=editor.figure.value.references.find(r=>r.id===id);if(!ref)throw new Error('所选参考图已变化，请重新选择');return{id:ref.id,title:ref.title,citation:ref.citation,fileName:ref.fileName,sha256:ref.sha256,width:ref.pixelWidth,height:ref.pixelHeight,dataUrl:ref.dataUrl,purpose,...(ref.generated?{generated:ref.generated}:{})}})
  await drafts.start({requestId:crypto.randomUUID(),title:title.value,content:composition?.plan.goal??content.value,visual:visual.value,aspect:aspect.value,outputKind:composition?'figure':outputKind.value,timeoutSeconds:Number(timeout.value),...(model.value.trim()?{model:model.value.trim()}:{}),style:draftStyleSchema.parse({id,name,updatedAt,designSystem,paperTheme,fontRoles,preset,paletteId,fontFamily,surface,colorIndex,colorMap,sketchStyle,roughness,lineStyle,guide}),references,...(composition?{composition}:{})})
}catch(e){error.value=(e as Error).message}}
async function prepareIllustration(run:ImageDraftRun){if(!run.origin||importing.value)return;importing.value=run.id;error.value='';try{const response=await fetch(`/api/image-drafts/runs/${run.id}/image`);if(!response.ok)throw new Error('插画图片已过期');const asset=await readImageAsset(await response.blob(),run.title,run.origin);editor.assetDialog.value={mode:'template',asset}}catch(cause){error.value=(cause as Error).message}finally{importing.value=''}}
async function importDraft(run:ImageDraftRun,rebuild=false){if(!run.origin||importing.value)return;importing.value=run.id;error.value='';const baseline=editor.figure.value
  try{const response=await fetch(`/api/image-drafts/runs/${run.id}/image`);if(!response.ok)throw new Error('草稿图片不可用，请刷新记录');const blob=await response.blob(),extension=blob.type==='image/png'?'png':blob.type==='image/jpeg'?'jpg':'webp',file=new File([blob],`ai-draft-${run.id}.${extension}`,{type:blob.type}),reference=await readGeneratedReference(file,run.origin,editor.currentContainer.value)
    if(editor.figure.value!==baseline)throw new Error('画布已变化，请重新导入草稿');if(!editor.addDraftReference(reference,run.origin))throw new Error(editor.notice.value)
    try{await drafts.review(run.id,'imported')}catch(e){error.value=`已导入当前图件，历史状态尚未更新：${(e as Error).message}`}
    if(rebuild)editor.requestReconstruction({kind:'reconstruct',referenceId:reference.id,region:{...wholeImage},destination:'new',parentId:editor.currentContainer.value.id},'将这张 AI 视觉草稿重建为可编辑图件。先对照保存的内容规格核对文字、结构和连线，再识别分区与图示；明确指出草稿虚构或与规格冲突之处，不把图片当作科学证据。')
  }catch(e){error.value=(e as Error).message}finally{importing.value=''}}
async function discard(id:string){try{await drafts.review(id,'discarded')}catch(e){error.value=(e as Error).message}}
async function download(run:ImageDraftRun){try{const response=await fetch(`/api/image-drafts/runs/${run.id}/image`);if(!response.ok)throw new Error('图片已过期');const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`ai-draft-${run.id}.${blob.type==='image/png'?'png':blob.type==='image/jpeg'?'jpg':'webp'}`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
const imported=(run:ImageDraftRun)=>editor.figure.value.references.some(r=>r.generated?.runId===run.id)
async function downloadBundle(run:ImageDraftRun){if(!run.origin)return;try{const response=await fetch(`/api/image-drafts/runs/${run.id}/image`);if(!response.ok)throw new Error('草稿图片已过期');const blob=await response.blob(),base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]!);reader.onerror=()=>reject(new Error('无法读取草稿'));reader.readAsDataURL(blob)}),bundle=imageDraftBundleSchema.parse({format:'fastfigure.image-draft',version:1,origin:run.origin,image:{mime:blob.type,base64}});downloadFile(`ai-draft-${run.id}.json`,JSON.stringify(bundle),'application/json')}catch(e){error.value=(e as Error).message}}
</script>
<template>
  <Box class="image-draft-panel">
    <Text class="panel-description">用 Codex 平台图像模型探索构图，核对后再重建为可编辑图元。</Text>
    <Box v-if="editor.imageDraftPlan.value" aria-label="草稿采用的绘图方案"><Text class="selection-title">沿用方案：{{ editor.imageDraftPlan.value.plan.title }}</Text><Text class="muted-caption">按方案保留分区、模块、参数与关系，通过图示细节增加视觉丰富度。</Text><Disclosure><DisclosureTrigger size="xs">查看草稿方案</DisclosureTrigger><CompositionPlanView :record="editor.imageDraftPlan.value" disabled /></Disclosure><Button size="xs" variant="quiet" @click="editor.imageDraftPlan.value=null">清除草稿方案</Button></Box>
    <Field v-if="!editor.imageDraftPlan.value"><Text>生成用途</Text><Select :value="outputKind" :options="[{value:'figure',label:'整图视觉草稿'},{value:'illustration',label:'透明背景局部插画'}]" aria-label="生成用途" @change="outputKind=$event as 'figure'|'illustration'" /></Field><Field><Text>草稿名称</Text><TextField v-model="title" maxlength="100" aria-label="AI 草稿名称" /></Field><Field><Text>图要表达的内容与关系</Text><TextArea v-model="content" :readonly="!!editor.imageDraftPlan.value" rows="5" maxlength="6000" aria-label="AI 草稿内容规格" placeholder="模块、输入输出、关键关系、必须保留的标签；不确定的内容可明确说明。" /></Field><Field><Text>视觉要求</Text><TextArea v-model="visual" rows="3" maxlength="2000" aria-label="AI 草稿视觉要求" placeholder="构图、留白、手绘感、注释位置…" /></Field><Select v-if="!editor.imageDraftPlan.value" :value="styleId" :options="styleOptions" aria-label="AI 草稿风格" @change="styleId=$event" /><Select :value="aspect" :options="[{value:'landscape',label:'横向图件'},{value:'square',label:'方形图件'},{value:'portrait',label:'纵向图件'}]" aria-label="AI 草稿方向" @change="aspect=$event as ImageDraftInput['aspect']" />
    <Disclosure v-if="!editor.imageDraftPlan.value&&editor.figure.value.references.length"><DisclosureTrigger size="xs">选择参考图（{{ Object.keys(selected).length }}）</DisclosureTrigger><Box v-for="image in editor.figure.value.references" :key="image.id" class="image-draft-reference"><Field class="checkbox-field"><TextField type="checkbox" :checked="Object.hasOwn(selected,image.id)" :aria-label="`草稿参考图 ${image.title}`" @change="select(image.id,$event)" /><Text>{{ image.title }}</Text></Field><Select v-if="selected[image.id]" :value="selected[image.id]" :options="purposeOptions" :aria-label="`草稿参考用途 ${image.title}`" @change="selected={...selected,[image.id]:$event as ReferencePurpose}" /></Box></Disclosure>
    <Disclosure><DisclosureTrigger size="xs">模型与运行时限</DisclosureTrigger><Text class="muted-caption">{{ drafts.status.value }}</Text><Field><Text>文本模型（留空使用本机配置）</Text><TextField v-model="model" maxlength="100" aria-label="AI 草稿模型" /></Field><Select :value="timeout" :options="[{value:'60',label:'1 分钟'},{value:'180',label:'3 分钟'},{value:'360',label:'6 分钟'},{value:'600',label:'10 分钟'}]" aria-label="AI 草稿时限" @change="timeout=$event" /><Text class="muted-caption">图像模型由平台选择，具体版本以运行报告为准。</Text></Disclosure>
    <Text v-if="error||drafts.error.value" role="alert" class="error-text">{{ error||drafts.error.value }}</Text><Button variant="primary" :disabled="drafts.busy.value||running||!content.trim()" @click="generate">{{ drafts.pending.value?'重新提交同一请求':drafts.busy.value?'正在提交…':'生成一张草稿' }}</Button><Button v-if="drafts.pending.value&&!running" size="xs" variant="quiet" @click="drafts.pending.value=null">放弃待确认提交</Button><Text class="muted-caption">每次生成一张，先审阅；AI 草稿不作为实验依据。生成和可编辑重建分别运行。</Text>
    <Box class="image-draft-heading"><Heading>草稿记录</Heading><Button size="xs" variant="quiet" @click="drafts.refresh">刷新记录</Button></Box>
    <Box v-for="run in drafts.runs.value" :key="run.id" class="image-draft-card" :data-image-draft-id="run.id"><Text class="selection-title">{{ run.title }} · {{ run.status==='running'?'生成中':run.status==='failed'?'失败':run.status==='cancelled'?'已停止':run.review==='discarded'?'已舍弃':run.review==='imported'?'已导入过':'待审阅' }}</Text><Image v-if="run.available" :src="`/api/image-drafts/runs/${run.id}/image`" :alt="`AI 草稿 ${run.title}`" class="image-draft-image" /><Button v-if="run.available" size="xs" variant="quiet" :aria-label="`放大草稿 ${run.title}`" @click="previewId=run.id">放大查看</Button><Text v-if="run.error" class="error-text">{{ run.error }}</Text><Text v-if="run.status==='completed'&&!run.available" class="muted-caption">图片已过期，已导入工程的参考图与来源仍保留。</Text><Text v-if="run.status==='running'" class="muted-caption">{{ run.activities.at(-1) }}</Text><Button v-if="run.status==='running'" size="xs" @click="drafts.cancel(run.id)">停止生成</Button><template v-if="run.available&&run.review!=='discarded'"><Button v-if="run.outputKind==='illustration'" size="xs" variant="primary" :disabled="!!importing" :aria-label="`使用插画 ${run.title}`" @click="prepareIllustration(run)">预览为图片组件</Button><Button size="xs" :disabled="!!importing||imported(run)" :aria-label="`导入草稿 ${run.title}`" @click="importDraft(run)">{{ imported(run)?'已在当前参考图中':'导入为参考图' }}</Button><Button size="xs" variant="primary" :disabled="!!importing||imported(run)" :aria-label="`重建草稿 ${run.title}`" @click="importDraft(run,true)">导入并准备重建</Button><Button size="xs" variant="quiet" @click="download(run)">下载原图</Button><Button size="xs" variant="quiet" :aria-label="`导出草稿包 ${run.title}`" @click="downloadBundle(run)">导出草稿包</Button><Button v-if="run.review==='pending'" size="xs" variant="quiet" @click="discard(run.id)">舍弃草稿</Button></template><ImageDraftOriginView v-if="run.origin" :origin="run.origin" /></Box>
    <Modal :open="!!previewRun?.available" size="xl" label="AI 草稿大图" @close="previewId=''"><Header><Heading>{{ previewRun?.title }}</Heading></Header><ModalBody><Image v-if="previewRun?.available" :src="`/api/image-drafts/runs/${previewRun.id}/image`" :alt="`AI 草稿大图 ${previewRun.title}`" class="image-draft-large" /><Text class="muted-caption">视觉草稿，核对内容与结构后再重绘。</Text></ModalBody><Footer><Button @click="previewId=''">关闭大图</Button></Footer></Modal>
  </Box>
</template>
